RECORD = {
    "id": "JAH-NMJ2-000001",
    "name": "Sari",
    "kind": "first-name",
    "meaning": "Sari is a feminine given name in Javanese. Meaning: Essence. The core or best part; a classic girls' name."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Sar")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

